mapper.select:
select g.pk_grad_id_grado as id, ue.uned_rbd as rbd, ng.pk_nivel_grado_id as tipo, ng.nivel_grado_nombre as tipoNombre from grado g inner join unidad_educativa ue on ue.pk_uned_id_unidad_educativa = g.fk_grad_id_unidad_educativa inner join nivel_grado ng on ng.pk_nivel_grado_id = g.fk_grad_id_nivel_grado WHERE TRUE
AND g.fk_grad_id_unidad_educativa = #{unidadEducativa}
AND g.fk_grad_id_nivel_grado = #{tipo}
